#!/bin/sh
# Generates Formula/rubio.rb (Homebrew) and bucket/rubio.json (Scoop) for a release.
# Usage: scripts/packaging.sh vX.Y.Z path/to/SHA256SUMS
# Called by the release workflow; the two files are generated, do not edit them.
set -eu
tag="$1"; sums="$2"
ver="${tag#v}"
repo="dicapower/rubio-ia"
base="https://github.com/$repo/releases/download/$tag"

sum() { # sum <os-arch> <ext>
  f="rubio-$tag-$1.$2"
  h=$(grep "  $f\$" "$sums" | cut -d' ' -f1)
  [ -n "$h" ] || { echo "packaging: $f missing from $sums" >&2; exit 1; }
  printf '%s' "$h"
}

mkdir -p Formula bucket
cat > Formula/rubio.rb <<RB
# Generated by scripts/packaging.sh from the release checksums. Do not edit.
class Rubio < Formula
  desc "A short working agreement for AI coding agents"
  homepage "https://github.com/$repo"
  version "$ver"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$base/rubio-$tag-darwin-arm64.tar.gz"
      sha256 "$(sum darwin-arm64 tar.gz)"
    end
    on_intel do
      url "$base/rubio-$tag-darwin-amd64.tar.gz"
      sha256 "$(sum darwin-amd64 tar.gz)"
    end
  end

  on_linux do
    on_arm do
      url "$base/rubio-$tag-linux-arm64.tar.gz"
      sha256 "$(sum linux-arm64 tar.gz)"
    end
    on_intel do
      url "$base/rubio-$tag-linux-amd64.tar.gz"
      sha256 "$(sum linux-amd64 tar.gz)"
    end
  end

  def install
    bin.install "rubio"
  end

  def caveats
    <<~EOS
      Run: rubio setup, restart your agent, then rubio doctor
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/rubio version")
  end
end
RB

cat > bucket/rubio.json <<JSON
{
    "version": "$ver",
    "description": "A short working agreement for AI coding agents",
    "homepage": "https://github.com/$repo",
    "license": "Apache-2.0",
    "architecture": {
        "64bit": {
            "url": "$base/rubio-$tag-windows-amd64.zip",
            "hash": "$(sum windows-amd64 zip)",
            "extract_dir": "rubio-$tag-windows-amd64"
        }
    },
    "bin": "rubio.exe",
    "checkver": "github",
    "autoupdate": {
        "architecture": {
            "64bit": {
                "url": "https://github.com/$repo/releases/download/v\$version/rubio-v\$version-windows-amd64.zip",
                "extract_dir": "rubio-v\$version-windows-amd64"
            }
        }
    }
}
JSON
echo "packaging: wrote Formula/rubio.rb and bucket/rubio.json for $tag"
